#!/bin/bash
A=$(command -v agent-browser)
S=r18f2
D='docs/laiyipao/audits/round18-reaction-damage-impact'
echo STEP1_CLOSE
$A --session $S close >/dev/null 2>&1
echo STEP2_OPEN
$A --session $S set viewport 1440 900 2>&1
$A --session $S --init-script "$D/probe.js" open 'http://127.0.0.1:5175/laiyipao-admin/#/admin/dashboard' 2>&1
echo OPEN_RC=$?
sleep 6
echo STEP3_URL
$A --session $S eval -b 'bG9jYXRpb24uaHJlZg==' 2>&1
echo STEP4_INITIAL
$A --session $S eval -b '' 2>&1
echo STEP5_CLICK
$A --session $S click '.r18-view-damage' 2>&1
sleep 3
echo STEP6_AFTER
$A --session $S eval -b '' 2>&1
echo STEP7_SHOT_TOP
$A --session $S screenshot "$D/screenshots/r18-01-damage-top.png" 2>&1
echo STEP8_SCROLL
$A --session $S scroll down 500 2>&1
sleep 1
echo STEP9_SHOT_SCROLL
$A --session $S screenshot "$D/screenshots/r18-02-damage-scroll.png" 2>&1
echo DONE
